from lib import *
S = SS('w25')
steps = [
    step("en0 上的邻居缓存(ndp -an)有 172 项(另有 5 项 incomplete):状态 STALE 169、REACHABLE 3——绝大多数邻居处于“没用过、需要时再确认”的 STALE。剩余过期时间最长 24.0 小时,最短只有 3 秒。接口参数(ndp -i en0):基础可达时间 30 秒,随机化后当前的可达时间 15 秒,NS 重传间隔 1 秒,标志 PERFORMNUD(做邻居不可达检测)和 DAD(做重复地址检测)。默认路由器列表有 4 项,但接口是 en0 的 0 项(其余是 utun 隧道接口);前缀列表里 en0 只有自己的链路本地前缀,标着“No advertising router”——en0 这条链路上没有收到过路由器通告(RA),所以没有 IPv6 默认路由器,也没有学到全球前缀。", t=tl(S(1)), mark=lidx(S(1), '默认路由器列表', '前缀列表里'), done=lidx(S(1), 'en0 上的邻居缓存', '过期时间', 'en0 的参数'), b=bars([['STALE', 169, '169'], ['REACHABLE', 3, '3'], ['incomplete', 5, '5']], 169, mark=[2], done=[0, 1]), kv=KV([['邻居缓存', '172 项 + 5 项 incomplete'], ['可达时间 / 重传', '15 秒 / 1 秒'], ['en0 上的路由器', '0 个:没收到过 RA'], ['结果', '没有 IPv6 默认路由器和全球前缀']], ['结果'])),
    step("对一个 STALE 邻居发一个 UDP 包,看邻居不可达检测(NUD):数据包立刻就发出去了,没有等 NUD。状态在后台变化:发包时刻进入 DELAY(D @ 0.0 s),5.3 秒时进入 PROBE(P @ 5.3 s),5.6 秒回到 REACHABLE(R @ 5.6 s)——DELAY 阶段约 5 秒;按规范,期间如果上层协议能证明对方可达(比如收到了 TCP 应答)就不必探测,这一点这里没有验证。到时间后抓包看到:本机在 5150.9 ms 发出单播的 NS(跳数限制 255,选项 1 = 本机的链路层地址),邻居在 5379.1 ms 单播回 NA,标志 R=0 S=1 O=1,选项 2 = 目标链路层地址。S=1 表示这是对 NS 的回应,所以本机把状态直接标成 REACHABLE。", t=tl(S(2)), mark=lidx(S(2), '本机 发 邻居请求 NS', '邻居 发 邻居通告 NA'), done=lidx(S(2), '状态变化', '线上共'), b=bars([['进入 DELAY', 0.0, '0.0 s'], ['发出单播 NS', 5.15, '5.15 s'], ['收到 NA', 5.38, '5.38 s'], ['回到 REACHABLE', 5.6, '5.6 s']], 6, mark=[1, 2], done=[0, 3]), kv=KV([['STALE → DELAY', '发数据的那一刻'], ['DELAY → PROBE', '约 5 秒后'], ['PROBE', '单播 NS(不再用组播)'], ['NA 标志', 'R=0 S=1 O=1']], ['PROBE'])),
    step("解析一个不存在的邻居:往本链路上没人用的随机链路本地地址发 UDP,抓到发给它的 NS 4 个,时间是 0、1571.2、2581.7、4504.9 ms,相邻间隔 1571、1010、1923 ms。ndp -i 给的重传间隔是 1 秒,实测间隔在 1.0 到 1.9 秒之间不等,为什么比 1 秒长没有深究。每个 NS 的 IPv6 目的地址都是“被请求节点组播地址”(ff02::1:ff 加目标地址的后 24 位),以太网目的 MAC 是 33:33 加这个组播地址的后 4 字节,跳数限制 255,选项 1 里放的是本机 MAC。4.5 秒后这个地址在 ndp -an 里仍是 incomplete,再发一次 sendto 也成功返回(没有立刻报错)。被请求节点组播让绝大多数设备根本不用处理这个 NS,比 ARP 的广播安静得多。", t=tl(S(3)), mark=lidx(S(3), 'NS #1', 'NS #2', 'NS #3', 'NS #4'), done=lidx(S(3), '目标地址是随机', 'NS 之间的间隔', '之后 ndp -an'), b=bars([['NS #2 距 #1', 1571, '1571 ms'], ['NS #3 距 #2', 1010, '1010 ms'], ['NS #4 距 #3', 1923, '1923 ms']], 1923, mark=[0, 2], done=[1]), kv=KV([['NS 目的', '被请求节点组播 ff02::1:ff__:____'], ['以太网目的 MAC', '33:33 + 组播地址的后 4 字节'], ['重传', '4 个 NS,间隔 1.0~1.9 秒'], ['之后', '仍是 incomplete']], ['NS 目的'])),
    step("ND 报文拆开看:一个 NS 的 ICMPv6 部分是 87 00 f7 9b 00 00 00 00 + 16 字节目标地址 + 01 01 + 6 字节 MAC:类型 135、代码 0、校验和 0xf79b、4 字节保留、目标地址,然后是选项——类型 1(源链路层地址)、长度 1(单位 8 字节,即 2 字节头加 6 字节 MAC)。抓到的 6 个 ND 报文跳数限制全是 255,校验和全部正确。类型号:133 RS、134 RA、135 NS、136 NA、137 重定向。NA 标志位:R(发送者是路由器)、S(对 NS 的回应)、O(覆盖旧缓存记录)。组播 MAC 映射:IPv6 组播地址后 4 字节接在 33:33 后面。用普通的 ICMPv6 套接字发类型 133 的路由器请求会失败(Operation not permitted):ND 报文只能由内核发,应用不能伪造,也就伪造不了跳数限制 255。", t=tl(S(4)), mark=lidx(S(4), '一个 NS 的 ICMPv6 部分', '全部 6 个', '用普通 ICMPv6 套接字'), done=lidx(S(4), '= 类型 135', '类型号', '组播 MAC 映射'), kv=KV([['NS', '类型 135 + 4 字节保留 + 目标地址 + 选项'], ['选项', '类型 1 / 长度 1×8 = 8 字节 = MAC'], ['跳数限制', '全部 255'], ['应用', '发不出 ND 报文(EPERM)']], ['跳数限制'])),
    step("和 IPv4 的 ARP 缓存对比(同一个 en0):ARP 缓存 274 项(其中 incomplete 2 项),NDP 缓存 172 项(+5 项 incomplete)。IPv4 的 ARP 表项最长保留 net.link.ether.inet.max_age = 1200 秒;IPv6 的 STALE 项最长可保留约 24.0 小时,但不是真的信任这么久:下次使用时才用单播 NS 探测邻居(见第二节)。NDP 比 ARP 多了状态机(REACHABLE / STALE / DELAY / PROBE),ARP 靠定时器过期后重新广播,NDP 在使用时才用单播探测。", t=tl(S(5)), mark=lidx(S(5), 'IPv4:net.link.ether'), done=lidx(S(5), 'ARP 缓存(arp -an)', 'ARP 缓存里是'), b=bars([['ARP 缓存(IPv4)', 274, '274 项'], ['NDP 缓存(IPv6)', 172, '172 项']], 274, mark=[1], done=[0]), kv=KV([['ARP 表项', '最长 1200 秒'], ['NDP STALE 项', '最长约 24 小时,使用时再确认'], ['NDP 多的', '状态机 + 单播探测']], ['NDP STALE 项'])),
]
A = mkartw('w25', 25, '网络协议,NDP,邻居发现,NS,NA,NUD,IPv6,真实验证,动画演示',
    '实测 IPv6 邻居发现:STALE 邻居在发数据后经过 DELAY(约 5 秒)进入 PROBE,单播 NS 得到 NA 后回到 REACHABLE;解析不存在的邻居时 NS 发往被请求节点组播地址、重传 4 次;ND 报文跳数限制全是 255;en0 上没有收到过路由器通告。',
    'IPv6 没有 ARP,邻居的链路层地址怎么解析?“邻居不可达检测”到底是怎样的状态机?为什么 ND 报文的跳数限制必须是 255?这篇在本机的 en0 上抓真实的 NS/NA,让一个邻居从 STALE 走到 REACHABLE,再去解析一个不存在的地址。',
    [('5.15 s', '对 STALE 邻居发数据后,DELAY 阶段结束、本机发出单播 NS 的时刻;5.38 s 收到 NA'), ('4 个 NS', '解析不存在的邻居时在 4.5 秒内发出的 NS 个数,间隔 1.0~1.9 秒,发往被请求节点组播地址'), ('255', '抓到的全部 ND 报文的跳数限制;应用用普通套接字发 RS 会被拒绝')],
    [('缓存与状态', '<p>邻居缓存里绝大多数是 STALE(没用过、需要时再确认),REACHABLE 很少。en0 上没有收到过路由器通告,所以既没有默认路由器,也没有学到全球前缀。</p>'),
     ('邻居不可达检测', '<p>往 STALE 邻居发数据后:先 DELAY 约 5 秒,若上层没有确认可达就进入 PROBE,单播 NS,收到 NA 后回到 REACHABLE。数据包本身不等这个过程。</p>'),
     ('地址解析', '<p>解析新邻居时 NS 发往目标地址对应的被请求节点组播地址,以太网目的 MAC 是 33:33 加后 4 字节;解析一个不存在的邻居时,4.5 秒内发了 4 个 NS(1 个首发加 3 次重传)。</p>'),
     ('报文格式', '<p>NS 是类型 135 + 4 字节保留 + 16 字节目标地址 + 选项(类型 1 = 源链路层地址);NA 多了 R / S / O 三个标志。跳数限制必须是 255,表明没有经过路由器,应用不能伪造 ND 报文。</p>'),
     ('对比 ARP', '<p>ARP 靠广播和定时器;NDP 用多播的被请求节点组减少打扰,并用单播探测验证邻居的可达性。</p>')],
    steps,
    [ENV_W + '。邻居与路由器的地址一律不写出,只写个数与状态;第二节选取的邻居是随机选的一个 STALE 项,发一个 UDP 包即可触发 NUD;第三节的地址是随机生成的、本链路上没有人用的链路本地地址;本机网络没有 IPv6 路由器,所以没有观察到 RS / RA',
     '没有验证:路由器请求 / 通告(RS / RA)的抓包与前缀选项;SLAAC 的重复地址检测(DAD,本机的 DAD 发生在接口启动时,没有重放);重定向(类型 137);NS 重传间隔为什么比 1 秒长;incomplete 状态最终多久放弃、应用会收到什么错误;邻居通告里的 O 标志在地址变化时的作用'],
    '邻居发现 NDP')
